//! Parity gate: assert every Python-oracle case in `todict_fixture.txt`
//! serialises to the identical canonical JSON bytes in Rust.
//!
//! The fixture is generated by `tests/todict_oracle.py`, which builds the real
//! Python `CostPreview`, `SourceRef` and `Quote` objects under the project venv
//! and records `json.dumps(obj.to_dict(), sort_keys=True, separators=(",",
//! ":"), allow_nan=False)`. Rust rebuilds the same typed field maps, converts
//! them to `ezchain_jsoncanon::JsonValue` and requires byte-for-byte equality.
//! A failure here is a parity failure, not a test bug: fix the implementation
//! and regenerate from the oracle, never edit the fixture to go green.

use ezchain_decimal::{
    todict::{CostPreviewRecord, DictValue, QuoteRecord, SourceRef, UtcDateTime},
    Decimal,
};
use ezchain_jsoncanon::{canonical_json, JsonValue};

const FIXTURE: &str = include_str!("todict_fixture.txt");

/// The committed fixture is used by default; `EZ_TODICT_FIXTURE` lets a
/// held-out corpus (generated with a different seed) be checked without
/// overwriting it.
fn fixture_text() -> String {
    match std::env::var("EZ_TODICT_FIXTURE") {
        Ok(path) => std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("cannot read held-out fixture {path}: {err}")),
        Err(_) => FIXTURE.to_string(),
    }
}

fn to_json(value: DictValue) -> JsonValue {
    match value {
        DictValue::Null => JsonValue::Null,
        DictValue::Bool(flag) => JsonValue::Bool(flag),
        DictValue::Int(number) => JsonValue::Int(number.to_string()),
        DictValue::Str(text) => JsonValue::Str(text),
        DictValue::Object(fields) => JsonValue::Object(
            fields
                .into_iter()
                .map(|(key, value)| (key.to_string(), to_json(value)))
                .collect(),
        ),
        DictValue::Array(items) => JsonValue::Array(items.into_iter().map(to_json).collect()),
    }
}

fn to_json_object(fields: Vec<(&'static str, DictValue)>) -> JsonValue {
    JsonValue::Object(
        fields
            .into_iter()
            .map(|(key, value)| (key.to_string(), to_json(value)))
            .collect(),
    )
}

fn parse_dec(text: &str) -> Decimal {
    Decimal::parse(text).unwrap_or_else(|err| panic!("bad decimal lexeme {text:?}: {err:?}"))
}

fn opt_dec(text: &str) -> Option<Decimal> {
    if text == "N" {
        None
    } else {
        Some(parse_dec(text))
    }
}

fn opt_str(text: &str) -> Option<String> {
    if text == "N" {
        None
    } else {
        Some(text.to_string())
    }
}

fn opt_i64(text: &str) -> Option<i64> {
    if text == "N" {
        None
    } else {
        Some(text.parse().expect("valid integer in fixture"))
    }
}

fn parse_u32(text: &str) -> u32 {
    text.parse().expect("valid datetime component in fixture")
}

/// Consume the nine source tokens: name, url, y, mo, d, h, mi, s, us.
fn build_source(fields: &[&str]) -> SourceRef {
    debug_assert_eq!(fields.len(), 9);
    SourceRef {
        name: fields[0].to_string(),
        url: opt_str(fields[1]),
        observed_at: UtcDateTime {
            year: fields[2].parse().expect("valid year in fixture"),
            month: parse_u32(fields[3]),
            day: parse_u32(fields[4]),
            hour: parse_u32(fields[5]),
            minute: parse_u32(fields[6]),
            second: parse_u32(fields[7]),
            microsecond: parse_u32(fields[8]),
        },
    }
}

fn run_case(fields: &[&str]) -> (String, JsonValue) {
    match fields[0] {
        "S" => {
            let source = build_source(&fields[1..10]);
            (
                fields[10].to_string(),
                to_json_object(source.to_dict().fields()),
            )
        }
        "C" => {
            let preview = CostPreviewRecord {
                platform_fee_usd: parse_dec(fields[1]),
                venue_fee_usd: parse_dec(fields[2]),
                network_fee_usd: opt_dec(fields[3]),
                price_impact_pct: opt_dec(fields[4]),
                slippage_bps: opt_i64(fields[5]),
                worst_case_out: opt_dec(fields[6]),
                fill_fee_usd: parse_dec(fields[7]),
                source: build_source(&fields[8..17]),
            };
            (
                fields[17].to_string(),
                to_json_object(preview.to_dict().fields()),
            )
        }
        "Q" => {
            let quote = QuoteRecord {
                chain: fields[1].to_string(),
                token_in: fields[2].to_string(),
                token_out: fields[3].to_string(),
                side: fields[4].to_string(),
                amount_in: parse_dec(fields[5]),
                amount_out: parse_dec(fields[6]),
                price: parse_dec(fields[7]),
                price_impact_pct: opt_dec(fields[8]),
                fee_usd: parse_dec(fields[9]),
                kind: fields[10].to_string(),
                route: opt_str(fields[11]),
                source: build_source(&fields[12..21]),
            };
            (
                fields[21].to_string(),
                to_json_object(quote.to_dict().fields()),
            )
        }
        other => panic!("unknown fixture kind {other:?}"),
    }
}

#[test]
fn to_dict_matches_python_oracle() {
    let fixture = fixture_text();
    let mut matched = 0usize;
    let mut by_kind: std::collections::BTreeMap<&str, usize> = std::collections::BTreeMap::new();
    for (index, line) in fixture.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        let (expected, value) = run_case(&fields);
        let actual = canonical_json(&value).expect("to_dict field map must be serialisable");
        assert_eq!(
            actual,
            expected,
            "case {} (kind {}) parity failure",
            index + 1,
            fields[0]
        );
        *by_kind.entry(fields[0]).or_default() += 1;
        matched += 1;
    }
    assert!(matched > 0, "fixture contained no cases");
    println!(
        "to_dict parity: {matched}/{matched} cases matched ({})",
        by_kind
            .iter()
            .map(|(kind, count)| format!("{kind}={count}"))
            .collect::<Vec<_>>()
            .join(", ")
    );
}

#[test]
fn utc_datetime_isoformat_spelling() {
    // Zero microseconds omit the fraction; a non-zero value is always six
    // digits; the UTC offset is always present. These are the three shapes
    // Python's `datetime.isoformat()` produces after UTC normalisation.
    let dt = |us| UtcDateTime {
        year: 2026,
        month: 11,
        day: 18,
        hour: 10,
        minute: 30,
        second: 15,
        microsecond: us,
    };
    assert_eq!(dt(0).isoformat(), "2026-11-18T10:30:15+00:00");
    assert_eq!(dt(7).isoformat(), "2026-11-18T10:30:15.000007+00:00");
    assert_eq!(dt(123456).isoformat(), "2026-11-18T10:30:15.123456+00:00");
    assert_eq!(dt(999_999).isoformat(), "2026-11-18T10:30:15.999999+00:00");
}
